var i=`0350-reibekuchen`;var n=`world-0350`;var o=`DE`;var s=`western-europe`;var a=4;var l=32;var r={en:`Reibekuchen`,ua:`Райбекухен`};var u={en:`A traditional Germany dish made with potato, yellow onion, chicken egg, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: картопля, жовта цибуля, куряче яйце, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:8,i:[[`potato`,850,`g`],[`yellow-onion`,130,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,65,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`sunflower-oil`,95,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`apple-sauce`,180,`g`]]}];var d={slug:i,id:n,country:`DE`,region:s,servings:4,minutes:32,title:r,text:u,steps:g};export{o as country,d as default,n as id,l as minutes,s as region,a as servings,i as slug,g as steps,u as text,r as title};